const allItems = $input.all();
if (allItems.length === 0 || !allItems[0].json.agent) {
  return [{ json: { _valid: false, _msg: 'No approved research data found. Run Stage 1 first and approve it.' } }];
}
const gen_run_id = $('Webhook').first().json.body.generation_run_id;
const pain = allItems.find(i => i.json.agent === 'pain');
const triggers = allItems.find(i => i.json.agent === 'triggers');
return [{ json: {
  _valid: true,
  generation_run_id: gen_run_id,
  pain_output: pain ? pain.json.output : null,
  triggers_output: triggers ? triggers.json.output : null
} }];

