const raw = $input.first().json.choices[0].message.content;
let parsed;
try { parsed = JSON.parse(raw); } catch(e) {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : {};
}
return [{ json: { persona_output: parsed } }];

